import{_ as o,c as e,o as i,ah as t}from"./chunks/framework.BkHe6ehV.js";const p=JSON.parse('{"title":"Qwen 系列","description":"","frontmatter":{"title":"Qwen 系列","date":"2025-12-06 11:51:44","create":"2025-12-06 11:51:44","categories":[],"tags":[],"readingStats":{"words":10270,"minutes":31,"images":4}},"headers":[],"relativePath":"posts/llm/industry/mainllm/05-qwen-series.md","filePath":"posts/llm/industry/mainllm/05-qwen-series.md","lastUpdated":1785944275000}'),n={name:"posts/llm/industry/mainllm/05-qwen-series.md"};function s(c,l,r,d,a,u){return i(),e("div",null,l[0]||(l[0]=[t('<h2 id="变化点" tabindex="-1">变化点 <a class="header-anchor" href="#变化点" aria-label="Permalink to &quot;变化点&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">2026</div><p><strong>2026.08 · <a href="#_2608-qwen3-8-2-4t-a95b-长程-agent">Qwen3.8</a></strong></p><ul><li>扩大至 <code>2.4T 总参数 / 95B 激活</code>，继续强化长程 Agent 与工具执行。</li><li>结合 effort 控制和历史思考保留，调整不同任务的推理开销。</li></ul><p><strong>2026.06 · <a href="#_2606-qwen-agentworld-七域环境模型">Qwen-AgentWorld（环境模型）</a></strong></p><ul><li>用 <code>10M+</code> 七域轨迹训练环境反馈预测，形成可控 Language World Model。</li><li>CPT/SFT/RL 校准预测，可用于模拟环境，也可预热 Policy 的动作后果预测能力。</li></ul><p><strong>2026.04 · <a href="#_2604-qwen3-6-35b-a3b-thinking-preservation">Qwen3.6-35B-A3B</a></strong></p><ul><li>训练中强化 <code>Thinking Preservation</code>，保留跨轮推理状态。</li><li>减少长任务重复分析，提高小激活模型的连续执行能力。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">2026（续）</div><p><strong>2026.04 · <a href="#_2604-qwen3-5-omni-thinker–talker、aria、交互-rl">Qwen3.5-Omni</a></strong></p><ul><li>Thinker–Talker 统一图文音视频，ARIA 自适应交错文本和语音，实现流式生成。</li><li>Thinker 结合领域蒸馏、文本向音频 OPD 与交互 RL；Talker 结合 CPT、DPO 和 GSPO。</li></ul><p><strong>2026.03 · <a href="#_2603-qwen3-coder-next-可验证任务、专家蒸馏">Qwen3-Coder-Next</a></strong></p><ul><li>基于 Qwen3-Next，构建 <code>800K+</code> 可验证任务与执行环境，强化代码和 Agent 能力。</li><li>MidTrain、SFT 后分别训练领域专家，再蒸馏到统一模型，适配多种工具格式。</li></ul><p><strong>2026.02 · <a href="#_2602-qwen3-5-397b-a17b-混合注意力-原生多模态">Qwen3.5-397B-A17B</a></strong></p><ul><li>改用 <code>Gated DeltaNet + 全局注意力</code>，并引入原生多模态训练。</li><li>结合异步 RL 与路由重放，提高 Agent 训练效率和稳定性。</li></ul></div><div class="custom-block info"><div class="custom-block-title">2025</div><p><strong>2025.07 · <a href="#_2507-qwen3-coder-480b-a35b-code-rl-agent-rl">Qwen3-Coder</a></strong></p><ul><li>加强文件、仓库级代码预训练，形成 <code>480B-A35B</code> 代码基座。</li><li>由 Code RL 扩展到可执行环境中的 Agent RL。</li></ul><p><strong>2025.05 报告 · <a href="#_2505-qwen3-四阶段后训练、强到弱蒸馏">Qwen3</a></strong></p><ul><li>统一 thinking / non-thinking，通过四阶段后训练融合推理与通用能力。</li><li>大模型训练后进行强到弱蒸馏，将能力迁移至小模型。</li></ul></div><div class="custom-block note"><div class="custom-block-title">2024 及以前</div><p><strong>2024.12 报告 · <a href="#_2412-qwen2-5-18t、dpo-→-grpo">Qwen2.5</a></strong></p><ul><li>扩大高质量预训练数据至 <code>18T tokens</code>，强化知识、代码与数学。</li><li>后训练结合复杂指令 SFT、离线 DPO 与在线 GRPO。</li></ul><p><strong>2024.09 · <a href="#_2409-qwen2-5-coder-文件与仓库-cpt、sft-dpo">Qwen2.5-Coder</a></strong></p><ul><li>强化文件级、仓库级 CPT 与 FIM，学习跨文件代码关系。</li><li>执行验证筛选代码数据，再结合 SFT 与 DPO。</li></ul><p><strong>2024.07 报告 · <a href="#_2407-qwen2-7t、离线与在线-dpo">Qwen2</a></strong></p><ul><li>扩大多语言预训练，结合 GQA、Dense/MoE 与长上下文训练。</li><li>采用离线和在线 DPO，增强指令遵循与偏好对齐。</li></ul></div><h2 id="_2608-qwen3-8-2-4t-a95b-长程-agent" tabindex="-1">(2608) Qwen3.8 (2.4T-A95B, 长程 Agent) <a class="header-anchor" href="#_2608-qwen3-8-2-4t-a95b-长程-agent" aria-label="Permalink to &quot;(2608) Qwen3.8 (2.4T-A95B, 长程 Agent)&quot;">​</a></h2><div class="custom-block danger"><div class="custom-block-title">Qwen3.8 概况</div><p><strong>参考链接</strong></p><ul><li><a href="https://huggingface.co/Qwen/Qwen3.8-2.4T-A95B" target="_blank" rel="noreferrer">Model Card</a>、<a href="https://qwen.ai/blog?id=qwen3.8" target="_blank" rel="noreferrer">Qwen3.8-Max</a>。</li></ul><p><strong>架构与运行形态</strong></p><ul><li>面向研发、专业分析和长程 Agent，重点是完整执行任务和延续多轮推理。</li><li><code>2.4T-A95B</code> MoE；<code>92</code> 层按 <code>3×Gated DeltaNet + 1×Gated Attention</code> 组合。</li><li>递归状态降低长历史开销，周期性 Attention 补充精确检索；每层 <code>512</code> 个路由专家，激活 <code>10</code> 个。</li><li>开放权重为 text-only thinking 模型，原生 <code>256K</code>；Max 服务增加视觉、non-thinking、默认 <code>1M</code> 和工具。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">推理预算与历史保留</div><p><strong>两个控制项</strong></p><ul><li><code>reasoning_effort=xhigh / medium / low</code> 调整当前推理投入。</li><li><code>preserve_thinking</code> 将前轮分析与消息一并保留，后轮沿用已排除原因和未完成计划。</li><li>预算控制决定本轮思考深度，历史保留决定下一轮还能使用哪些推理信息。</li></ul><p><strong>训练与生成</strong></p><ul><li>预训练与后训练强化代码、专业任务和环境反馈处理；模型卡未展开完整 RL 配方。</li><li>权重建议 <code>temperature=1, top_p=0.95, top_k=20</code>，默认 <code>xhigh</code>。</li></ul></div><div class="custom-block important"><div class="custom-block-title">Qwen3.8-Max 公开表现</div><p><strong>同系列对照</strong></p><ul><li>相对 Qwen3.7-Max：Terminal-Bench 2.1 <code>74.5 → 86.6</code>，SWE-bench Pro <code>60.6 → 67.7</code>。</li><li>PaperBench <code>64.8 → 93.0</code>，为复现任务的分项评分；NL2Repo <code>47.2 → 55.9</code>。</li><li>Toolathlon Verified <code>49.7 → 72.5</code>，Automation-Bench <code>14.2 → 27.3</code>。</li><li>GPQA <code>92.4 → 92.6</code>；相较知识问答，本轮改善主要体现在完整 Agent 工作流。</li></ul><p><strong>评测条件</strong></p><ul><li>Terminal 使用 Claude Code，<code>avg@10, timeout=5h, max_tokens=131072</code>。</li><li>SWE-Pro 使用 Claude Code、<code>256K</code> 上下文和修正后的任务集。</li><li>PaperBench 使用 BasicAgent Code-Dev、Opus 4.6 judge，<code>3</code> 次平均，每次最多 <code>12h</code>。</li></ul></div><h2 id="_2606-qwen-agentworld-七域环境模型" tabindex="-1">(2606) Qwen-AgentWorld (七域环境模型) <a class="header-anchor" href="#_2606-qwen-agentworld-七域环境模型" aria-label="Permalink to &quot;(2606) Qwen-AgentWorld (七域环境模型)&quot;">​</a></h2><div class="custom-block info"><div class="custom-block-title">Qwen-AgentWorld（环境模型）</div><p><strong>核心内容</strong></p><ul><li>用 <code>10M+</code> 七域轨迹训练环境反馈预测，形成可控 Language World Model。</li><li>CPT/SFT/RL 校准预测，可用于模拟环境，也可预热 Policy 的动作后果预测能力。</li></ul><p><strong>详细笔记</strong></p><ul><li><a href="./../../../domain/swe/10-swe-env.html#_2606-qwen-agentworld-10m-七域轨迹-lwm预热swe-v-3-39pt">阅读笔记</a></li></ul></div><h2 id="_2604-qwen3-6-35b-a3b-thinking-preservation" tabindex="-1">(2604) Qwen3.6-35B-A3B (Thinking Preservation) <a class="header-anchor" href="#_2604-qwen3-6-35b-a3b-thinking-preservation" aria-label="Permalink to &quot;(2604) Qwen3.6-35B-A3B (Thinking Preservation)&quot;">​</a></h2><div class="custom-block danger"><div class="custom-block-title">Qwen3.6-35B-A3B</div><p><strong>参考链接</strong></p><ul><li><a href="https://huggingface.co/Qwen/Qwen3.6-35B-A3B" target="_blank" rel="noreferrer">Model Card</a>、<a href="https://qwen.ai/blog?id=qwen3.6-35b-a3b" target="_blank" rel="noreferrer">官方发布</a>。</li></ul><p><strong>架构与目标</strong></p><ul><li>面向定位、编辑、测试和错误恢复的多轮 Coding Agent。</li><li><code>35B-A3B</code> 多模态 MoE；<code>40</code> 层、<code>3:1</code> Gated DeltaNet / Gated Attention，原生 <code>256K</code>。</li><li>每层 <code>256</code> 个路由专家，激活 <code>8</code> 个并使用共享专家；采用多步 MTP。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">Thinking Preservation</div><p><strong>历史推理适配</strong></p><ul><li>默认保留当前用户轮次内部的 thinking，较早用户轮次的 thinking 会被清除。</li><li>Qwen3.6 额外训练模型读取历史推理；开启 <code>preserve_thinking=True</code> 后沿用前轮分析。</li><li>例如保留已排查的调用关系，后轮继续验证修改，减少重复分析。</li></ul><p><strong>运行控制</strong></p><ul><li><code>enable_thinking</code> 控制当前是否思考；<code>preserve_thinking</code> 控制是否保留历史思考。</li><li>历史保留会增加输入长度，需要与工具输出共同管理；复杂任务建议至少 <code>128K</code> 上下文。</li></ul></div><div class="custom-block important"><div class="custom-block-title">同规模版本升级结果</div><p><strong>代码与工具任务</strong></p><ul><li>相对 Qwen3.5-35B-A3B：SWE-bench Verified <code>70.0 → 73.4</code>，Pro <code>44.6 → 49.5</code>。</li><li>Terminal-Bench 2.0 <code>40.5 → 51.5</code>，NL2Repo <code>20.5 → 29.4</code>，收益扩展到终端和整项目执行。</li><li>SWE 使用内部 bash/file-edit harness、<code>200K</code> 上下文；Terminal 使用 Terminus-2、<code>3h</code> 超时、<code>5</code> 次平均。</li></ul><p><strong>执行稳定性</strong></p><ul><li>Claw-Eval Avg <code>65.4 → 68.7</code>，Pass^3 <code>51.0 → 50.0</code>；平均效果提高，连续成功率仍有短板。</li><li>MMLU-Pro <code>85.3 → 85.2</code>，知识分数基本持平；这些是整体版本升级效果。</li></ul></div><h2 id="_2604-qwen3-5-omni-thinker–talker、aria、交互-rl" tabindex="-1">(2604) Qwen3.5-Omni (Thinker–Talker、ARIA、交互 RL) <a class="header-anchor" href="#_2604-qwen3-5-omni-thinker–talker、aria、交互-rl" aria-label="Permalink to &quot;(2604) Qwen3.5-Omni (Thinker–Talker、ARIA、交互 RL)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">Qwen3.5-Omni 论文摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://www.alphaxiv.org/abs/2604.15804" target="_blank" rel="noreferrer">paper</a>、<a href="https://huggingface.co/spaces/Qwen/Qwen3.5-Omni-Online-Demo" target="_blank" rel="noreferrer">demo</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>音视频理解、语言推理与流式语音生成需要统一，同时维持长上下文与低延迟。</li><li>文本与语音 Token 速率不同，固定对齐容易漏词、错读；音频提问的回答质量也弱于文本提问。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>流式架构</strong>：Thinker–Talker 均采用 Hybrid Attention MoE；ARIA 自适应交错文本、语音 tokens。</li><li><strong>Omni 预训练</strong>：编码器对齐 → 全参数图文音视频联合训练 → <code>256K</code> 长上下文扩展。</li><li><strong>Thinker 后训练</strong>：领域专家 SFT/RL → 专家蒸馏 → 文本向音频 OPD → 多轮交互 RL。</li><li><strong>Talker 后训练</strong>：大规模语音训练 → 高质量 CPT → DPO + GSPO → 轻量说话人微调。</li></ul><p><strong>模型效果(Qwen3.5-Omni-Plus + 蒸馏/RL)</strong></p><ul><li><strong>VoiceBench</strong> <code>93.1</code>，Gemini-3.1 Pro 为 <code>88.9</code>；FLEURS Top60 ASR WER 为 <code>6.55</code>。</li><li><strong>SEED-TTS</strong>：英文 WER 从 Qwen3-Omni 的 <code>1.39</code> 降至 <code>1.26</code>；中文为 <code>0.99</code>。</li><li><strong>OmniGAIA</strong>：多模态工具使用 <code>57.2</code>；Gemini-3.1 Pro 为 <code>68.9</code>。</li></ul><p><strong>重要结论</strong></p><ul><li>扩展音频交互后仍保留同级 Qwen3.5 的主要文本、视觉能力，但各任务收益不同；视频理解提升更明显。</li><li>单语说话人微调可迁移到多语言，模型无需为每种目标语言分别训练同一音色。</li></ul><p><strong>核心贡献</strong></p><ul><li>统一多模态理解、实时语音与工具动作；提出 ARIA，改善流式文字—语音对齐。</li></ul><p><strong>未来方向</strong></p><ul><li>以原生多模态训练为基础，发展能够实时理解、交互与行动的通用 Omni Agent。</li></ul></div><h3 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">多模态理解与实时语音的衔接</div><p><strong>跨模态交互质量不一致</strong></p><ul><li>同一问题改成语音输入后，回答的流畅性、推理与任务完成质量下降。</li><li>长对话还会出现意外语言切换、人设变化和指令遗忘，需要直接优化多轮交互。</li></ul><p><strong>流式生成与长序列成本</strong></p><ul><li>文本、语音 Tokenizer 的编码速率不同，固定交错比例容易造成漏词、发音和数字朗读错误。</li><li>长音视频的 KV Cache 与稀疏时间位置影响效率和时间理解，限制实时服务并发。</li></ul></div><h3 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="thinker–talker-与流式生成" tabindex="-1">Thinker–Talker 与流式生成 <a class="header-anchor" href="#thinker–talker-与流式生成" aria-label="Permalink to &quot;Thinker–Talker 与流式生成&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">理解与语音生成分工</div><p><strong>Thinker：多模态输入与文本输出</strong></p><ul><li>图像、视频通过视觉编码器；音频通过 <strong>AuT</strong>，与文本组成统一输入序列。</li><li>生成文本、工具调用和高层表示，支持搜索、Function Call 与音视频指令 Coding。</li><li>Thinker 与 Talker 均采用 <code>Hybrid Attention MoE</code>；Gated DeltaNet 减少长序列 KV 访问。</li></ul><p><strong>Talker：上下文相关的语音输出</strong></p><ul><li>接收历史文本、多模态表示与当前流式文本，决定语音内容、语调、音量和情绪。</li><li>自回归预测 RVQ 语音码；轻量 <strong>MTP</strong> 补全当前帧的残差 Codebooks。</li><li><strong>Code2Wav</strong> 使用因果 ConvNet，逐帧合成波形；无需等待完整句子或全部语音 tokens。</li></ul></div><div class="custom-block note"><div class="custom-block-title">ARIA 自适应文字—语音对齐</div><p><strong>单流交错生成</strong></p><ul><li>原先的文本、语音双轨改成一个交错序列，减少两个生成轨道之间的同步开销。</li><li>对任意前缀，累计语音 / 文本 Token 比例不超过该样本的整体比例。</li><li>以样本自身比例适配不同语言，不依赖固定交错速率或 MFA 强制对齐。</li><li>支持先给定任意长度的文本前缀，再继续生成连贯语音。</li></ul><p><strong>流式输入与声音控制</strong></p><ul><li><strong>Chunked Prefill</strong>：音视频按时间分块处理，提前启动 Thinker 和 Talker。</li><li><strong>Talker System Prompt</strong>：用文字描述、参考语音 Codec 指定音色，支持 Zero-Shot Voice Cloning。</li><li>上下文与指令共同控制语速、音量、情绪；原生轮次意图识别支持语义打断。</li></ul></div><h4 id="多模态预训练与上下文扩展" tabindex="-1">多模态预训练与上下文扩展 <a class="header-anchor" href="#多模态预训练与上下文扩展" aria-label="Permalink to &quot;多模态预训练与上下文扩展&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">AuT 音频编码与时间同步</div><p><strong>AuT 编码器训练</strong></p><ul><li>从头训练音频 Encoder–Decoder，使用 Qwen3-ASR 生成的音频—文本配对数据。</li><li>Mel 特征经 <code>4层 Conv2D</code> 下采样 <code>16倍</code>，输出频率 <code>6.25Hz</code>，每帧约对应 <code>160ms</code> 音频。</li><li>动态 Attention Window 训练，兼顾实时 Prefill Cache 与离线音频理解。</li></ul><p><strong>音视频时间对齐</strong></p><ul><li>沿用 TM-RoPE，为音频、视频分配按实际时间对应的位置编号。</li><li>每个视频时间块加入秒级文本时间戳，音频随机间隔插入时间戳。</li><li>显式时间文本补充位置编码，改善长音视频中的时间定位与跨模态同步。</li></ul></div><div class="custom-block important"><div class="custom-block-title">三阶段 Omni 预训练</div><p><strong>编码器对齐</strong></p><ul><li>LLM 与视觉编码器初始化自 <strong>Qwen3.5</strong>，音频编码器初始化自 <strong>AuT</strong>。</li><li>冻结 LLM，图像—文本和音频—文本分别训练；先训练 Adapter，再训练对应编码器。</li></ul><p><strong>联合训练与长上下文</strong></p><ul><li><strong>General Stage</strong>：解冻全部参数，混合纯文本、图文、音文、视频、音视频及音视频文本。</li><li>从早期同时加入单模态与跨模态数据，使用多样自然语言指令覆盖不同理解任务。</li><li><strong>Long Context Stage</strong>：提高长音频、长视频比例，将序列长度从 <code>32K</code> 扩展到 <code>256K</code>。</li><li>统一输入支持长音频理解与带声音的视频，输出可包含场景分段、时间戳与人物—声音对应。</li></ul></div><h4 id="thinker-领域蒸馏与交互-rl" tabindex="-1">Thinker 领域蒸馏与交互 RL <a class="header-anchor" href="#thinker-领域蒸馏与交互-rl" aria-label="Permalink to &quot;Thinker 领域蒸馏与交互 RL&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">领域能力整合与文本—音频迁移</div><p><strong>Specialist Distillation</strong></p><ul><li>从预训练 Qwen3.5 Base 分别训练文本、视觉、音频等领域教师，各自执行 SFT 与 RL。</li><li>文本领域覆盖 Agent、Coding 与基础推理；教师生成领域数据，再蒸馏到统一 Thinker。</li><li>对话统一为 ChatML，混合纯文本、视觉、音频和跨模态交互轨迹。</li></ul><p><strong>文本条件回答监督音频条件回答</strong></p><ul><li>同一问题保留音频与文本两种输入，先由文本条件生成高质量回答。</li><li>将该回答作为相应音频输入的蒸馏目标，执行报告中的 <strong>On-Policy Distillation</strong>。</li><li>重点缩小语音提问在推理、流畅性和任务完成度上的差距，保持两种输入行为一致。</li></ul></div><div class="custom-block note"><div class="custom-block-title">Interaction-Aligned RL</div><ul><li>构建多轮交互轨迹，直接覆盖长期对话中的语言、人设与指令约束。</li><li>围绕 <strong>语言一致性</strong>、<strong>人设稳定性</strong>、<strong>长上下文指令遵循</strong>设计奖励。</li><li>在领域蒸馏与文本—音频迁移之后继续 RL，优化完整交互体验。</li></ul></div><h4 id="talker-语音训练与偏好对齐" tabindex="-1">Talker 语音训练与偏好对齐 <a class="header-anchor" href="#talker-语音训练与偏好对齐" aria-label="Permalink to &quot;Talker 语音训练与偏好对齐&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">语音预训练与高质量 CPT</div><p><strong>General Stage</strong></p><ul><li>大规模多语言语音与多模态上下文配对，不只训练文字到声音的映射。</li><li>加入指令控制语音生成任务，让韵律、情绪和表达方式适应当前对话。</li></ul><p><strong>Long-Context Stage</strong></p><ul><li>对数据做质量分层，使用高质量子集继续预训练，减少噪声语料引入的幻觉。</li><li>结合 Qwen3-Omni-Captioner 增强语料，扩展到 <code>64K</code> 上下文。</li></ul></div><div class="custom-block important"><div class="custom-block-title">DPO、GSPO 与说话人微调</div><p><strong>人类偏好与规则反馈</strong></p><ul><li>人工标注多语言语音偏好对，用 <strong>DPO</strong> 优化自然度与表达质量。</li><li>结合规则奖励执行 <strong>GSPO</strong>，进一步提高任务能力与训练稳定性。</li></ul><p><strong>声音定制</strong></p><ul><li>最后执行轻量说话人微调，强化目标音色、自然度和可控表达。</li><li>与参考语音提示驱动的 Zero-Shot Voice Cloning 同时提供不同定制方式。</li></ul></div><h3 id="实验设置-qwen3-5-omni-plus-flash" tabindex="-1">实验设置(Qwen3.5-Omni-Plus / Flash) <a class="header-anchor" href="#实验设置-qwen3-5-omni-plus-flash" aria-label="Permalink to &quot;实验设置(Qwen3.5-Omni-Plus / Flash)&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">模型与训练数据</div><p><strong>模型和数据</strong></p><ul><li>评测 <strong>Plus</strong> 与 <strong>Flash</strong> 两个 Instruct 版本；输入窗口均为 <code>256K</code>。</li><li>总体训练语料包含超过 <code>1亿小时</code> 音视频；AuT 独立训练使用 <code>4000万小时</code> 音频—文本对。</li><li>AuT 中文、英文、其他语言比例 <code>3.5:3.5:3</code>；Talker 初始训练超过 <code>2000万小时</code> 多语言语音。</li><li>Omni General Stage 约 <code>4T tokens</code>；Thinker 长度 <code>32K</code> → <code>256K</code>，Talker CPT 扩展至 <code>64K</code>。</li></ul><p><strong>评测对象与条件</strong></p><ul><li><strong>文本、视觉</strong>：对照 Qwen3.5-Plus-Instruct；<strong>音频、音视频</strong>：对照 Gemini-3.1 Pro。</li><li><strong>OmniGAIA</strong>：不加 Thinking Prompt 与 Answer 格式，用 DeepSeek-V3.2-Thinking 做 Judge。</li><li><strong>语音生成</strong>：SEED-TTS、公开多语言 TTS、FLEURS 内部集与 CV3-Eval，测 WER / CER、Speaker Similarity。</li><li><strong>流式延迟</strong>：内部 vLLM，MTP 与 Codec 使用 Torch Compile / CUDA Graph；分别测 <code>1 / 4 / 8</code> 并发。</li></ul></div><h3 id="关键结果-qwen3-5-omni-plus-蒸馏-dpo-gspo" tabindex="-1">关键结果(Qwen3.5-Omni-Plus + 蒸馏/DPO/GSPO) <a class="header-anchor" href="#关键结果-qwen3-5-omni-plus-蒸馏-dpo-gspo" aria-label="Permalink to &quot;关键结果(Qwen3.5-Omni-Plus + 蒸馏/DPO/GSPO)&quot;">​</a></h3><div class="custom-block important"><div class="custom-block-title">音频理解与交互</div><p><strong>对照 Gemini-3.1 Pro</strong></p><ul><li><strong>VoiceBench</strong>：<code>88.9</code> → <code>93.1</code>，语音对话表现更强；<strong>MMAU</strong>：<code>81.1</code> → <code>82.2</code>。</li><li><strong>FLEURS Top60</strong>：ASR WER <code>7.32</code> → <code>6.55</code>；<strong>LibriSpeech clean / other</strong> 为 <code>1.11 / 2.23</code>。</li><li><strong>DailyOmni</strong>：<code>82.7</code> → <code>84.6</code>；<strong>Omni-Cloze</strong>：<code>57.2</code> → <code>64.8</code>，强化音视频理解与细节描述。</li><li><strong>OmniGAIA</strong>：<code>57.2</code>，仍低于 Gemini-3.1 Pro 的 <code>68.9</code>；工具使用还有差距。</li></ul></div><div class="custom-block note"><div class="custom-block-title">文本与视觉能力保留</div><ul><li>对照 <strong>Qwen3.5-Plus-Instruct</strong>，IFEval 同为 <code>89.7</code>；MMMU-Pro 为 <code>73.8</code> → <code>73.9</code>。</li><li>视频任务提高：MVBench <code>76.7</code> → <code>79.0</code>，LVBench <code>68.6</code> → <code>71.2</code>。</li><li>GPQA 为 <code>85.9</code> → <code>83.9</code>，LiveCodeBench v6 为 <code>67.1</code> → <code>65.6</code>，整体能力接近原同级模型。</li><li>多模态能力扩展与文本、视觉能力保留可以兼顾，但各任务收益并不相同。</li></ul></div><div class="custom-block important"><div class="custom-block-title">语音生成与流式效率</div><p><strong>语音准确性和声音迁移</strong></p><ul><li>对照 <strong>Qwen3-Omni-30B-A3B</strong>，SEED-TTS 中文 WER <code>1.07</code> → <code>0.99</code>，英文 <code>1.39</code> → <code>1.26</code>。</li><li>多语言 TTS 对照中，<code>29种语言</code>有 <code>22种</code>取得最低 WER，同时保留较高说话人相似度。</li><li>跨语言 Voice Cloning 的 <code>12个方向</code>中有 <code>10个</code>最优，覆盖不同原音色与目标语言组合。</li><li>仅用单语做说话人微调，目标声音仍能迁移到所测 <code>29种语言</code>。</li></ul><p><strong>首包与并发</strong></p><ul><li>单并发音频输入的理论首包延迟：Flash <code>235ms</code>，Plus <code>435ms</code>。</li><li>Plus 从 <code>1并发</code>扩到 <code>8并发</code>，音频首包为 <code>435ms</code> → <code>955ms</code>，Generation RTF 仍为 <code>0.334</code>。</li><li>生成速度快于实际播放速度，为连续语音输出保留缓冲余量。</li></ul></div><h3 id="未来方向" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block info"><div class="custom-block-title">通用 Omni Agent</div><ul><li>继续扩大原生多模态训练，使模型在同一系统内完成感知、推理、实时交互与工具行动。</li></ul></div><h2 id="_2603-qwen3-coder-next-可验证任务、专家蒸馏" tabindex="-1">(2603) Qwen3-Coder-Next (可验证任务、专家蒸馏) <a class="header-anchor" href="#_2603-qwen3-coder-next-可验证任务、专家蒸馏" aria-label="Permalink to &quot;(2603) Qwen3-Coder-Next (可验证任务、专家蒸馏)&quot;">​</a></h2><div class="custom-block info"><div class="custom-block-title">Qwen3-Coder-Next</div><p><strong>核心内容</strong></p><ul><li>基于 Qwen3-Next，构建 <code>800K+</code> 可验证任务与执行环境，强化代码和 Agent 能力。</li><li>MidTrain、SFT 后分别训练领域专家，再蒸馏到统一模型，适配多种工具格式。</li></ul><p><strong>详细笔记</strong></p><ul><li><a href="./../codellm/07-code-fulltrain-reading.html#_2603-qwen3-coder-next-70-6分-alibaba">阅读笔记</a></li></ul></div><h2 id="_2602-qwen3-5-397b-a17b-混合注意力-原生多模态" tabindex="-1">(2602) Qwen3.5-397B-A17B (混合注意力, 原生多模态) <a class="header-anchor" href="#_2602-qwen3-5-397b-a17b-混合注意力-原生多模态" aria-label="Permalink to &quot;(2602) Qwen3.5-397B-A17B (混合注意力, 原生多模态)&quot;">​</a></h2><div class="custom-block danger"><div class="custom-block-title">Qwen3.5 架构与预训练</div><p><strong>参考链接</strong></p><ul><li><a href="https://qwen.ai/blog?id=qwen3.5" target="_blank" rel="noreferrer">Qwen3.5: Towards Native Multimodal Agents</a>、<a href="https://huggingface.co/Qwen/Qwen3.5-397B-A17B" target="_blank" rel="noreferrer">Model Card</a>。</li></ul><p><strong>原生多模态</strong></p><ul><li>预训练即融合文本与视觉 tokens，扩展 STEM、视频、多语言材料并加强数据过滤。</li><li>语言与方言覆盖 <code>119 → 201</code>，词表约 <code>250K</code>；原生 <code>256K</code>，可扩展约 <code>1M</code>。</li></ul><p><strong>混合主干</strong></p><ul><li><code>397B-A17B</code>；<code>60</code> 层按 <code>3×Gated DeltaNet + 1×Gated Attention</code> 组合。</li><li>DeltaNet 控制长历史成本，全局 Attention 保留精确检索；多步 MTP 支持生成加速。</li><li><code>512</code> 个路由专家，激活 <code>10</code> 个并使用共享专家，降低 FFN 的每 token 计算量。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">多任务 RL 与异步训练</div><p><strong>环境扩展</strong></p><ul><li>扩展文本、多模态、多轮任务及任务难度，覆盖更多 Agent 执行环境。</li><li>异步解耦 rollout 与参数训练，动态分配负载并支持细粒度故障恢复。</li></ul><p><strong>稳定性与效率</strong></p><ul><li>Router Replay 复用采样时的专家路由；Multi-turn Rollout Locking 管理交互中的策略版本。</li><li>控制数据过期程度与任务采样平衡，减少异步等待和快慢任务造成的分布偏斜。</li><li>视觉编码器、语言主干采用异构并行；敏感计算保留 BF16，其他部分利用 FP8 加速。</li><li>官方报告 FP8 减少约一半激活显存，异步 RL 系统整体加速约 <code>3–5×</code>。</li></ul></div><div class="custom-block important"><div class="custom-block-title">多模态与 Agent 表现</div><p><strong>能力变化</strong></p><ul><li>对比 Qwen3-Max-Thinking：SWE-V <code>75.3 → 76.4</code>，Terminal-Bench 2.0 <code>22.5 → 52.5</code>。</li><li>LiveCodeBench v6 <code>85.9 → 83.6</code>，终端改善没有同步转为竞赛代码提升。</li><li>对比 Qwen3-VL-235B-A22B：MMMU-Pro <code>69.3 → 79.0</code>，MathVision <code>74.6 → 88.6</code>。</li></ul><p><strong>上下文策略</strong></p><ul><li>BrowseComp：simple context-folding <code>69.0</code>，discard-all <code>78.6</code>；结果依赖历史如何清理与重建。</li><li>多数搜索评测采用 <code>256K</code>；WideSearch 不做上下文管理，得分 <code>74.0</code>。</li></ul></div><h2 id="_2507-qwen3-coder-480b-a35b-code-rl-agent-rl" tabindex="-1">(2507) Qwen3-Coder (480B-A35B, Code RL + Agent RL) <a class="header-anchor" href="#_2507-qwen3-coder-480b-a35b-code-rl-agent-rl" aria-label="Permalink to &quot;(2507) Qwen3-Coder (480B-A35B, Code RL + Agent RL)&quot;">​</a></h2><div class="custom-block danger"><div class="custom-block-title">Qwen3-Coder 数据与模型</div><p><strong>参考链接</strong></p><ul><li><a href="https://qwenlm.github.io/blog/qwen3-coder/" target="_blank" rel="noreferrer">官方博客</a>、<a href="https://huggingface.co/Qwen/Qwen3-Coder-480B-A35B-Instruct" target="_blank" rel="noreferrer">Model Card</a>、<a href="https://github.com/QwenLM/Qwen3-Coder" target="_blank" rel="noreferrer">GitHub</a>。</li></ul><p><strong>训练基础</strong></p><ul><li>仓库任务需要代码知识、长上下文和执行反馈，单轮竞赛代码难以覆盖完整开发流程。</li><li><code>7.5T tokens</code>，代码占 <code>70%</code>；用 Qwen2.5-Coder 清洗、重写噪声数据。</li><li><code>480B-A35B</code> MoE，原生 <code>256K</code>，通过 YaRN 扩展至 <code>1M</code>，包含仓库和 PR 材料。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">Code RL 与 Agent RL</div><p><strong>执行反馈</strong></p><ul><li>Code RL 从竞赛题扩展到编辑、SQL、软件开发、多语言和数据分析。</li><li>自动扩展测试用例，通过代码执行结果提供奖励，利用“求解难、验证容易”的任务。</li></ul><p><strong>多轮训练</strong></p><ul><li>Agent RL 连续进行规划、工具调用、读取反馈和修改，学习根据失败测试调整方案。</li><li>云端系统支持最多 <code>20K</code> 个独立环境，为长轨迹持续提供交互和验证。</li></ul></div><div class="custom-block note"><div class="custom-block-title">Qwen Code 与工具接口</div><ul><li>Qwen Code 基于 Gemini CLI 改造，适配提示词、工具和 function-call 协议，也支持 Cline。</li><li>模型生成调用 → parser 解析 → harness 执行 → 结果回传，形成连续开发流程。</li><li>Instruct 权重为 non-thinking 模式；建议 <code>temperature=0.7, top_p=0.8, top_k=20</code>。</li></ul></div><div class="custom-block important"><div class="custom-block-title">公开代码评测</div><p><strong>交互预算</strong></p><ul><li>SWE-bench Verified + OpenHands：最多 <code>100</code> 轮得 <code>67.0</code>，<code>500</code> 轮得 <code>69.6</code>。</li><li>同框架 Sonnet 4 分别为 <code>68.0 / 70.4</code>；增加执行轮数能带来额外解决率。</li></ul><p><strong>任务覆盖</strong></p><ul><li>Terminal-Bench <code>37.5</code>，SWE Multilingual <code>54.7</code>，Aider-Polyglot <code>61.8</code>。</li><li>SWE-bench Live <code>26.3</code>，比 Verified 更困难，仓库修复能力仍受任务分布影响。</li><li>Code RL 曲线中编辑、SQL、开发等任务均有改善，说明执行反馈训练可以覆盖更多真实代码工作。</li></ul></div><h2 id="_2505-qwen3-四阶段后训练、强到弱蒸馏" tabindex="-1">(2505) Qwen3 (四阶段后训练、强到弱蒸馏) <a class="header-anchor" href="#_2505-qwen3-四阶段后训练、强到弱蒸馏" aria-label="Permalink to &quot;(2505) Qwen3 (四阶段后训练、强到弱蒸馏)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">Qwen3 摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://arxiv.org/abs/2505.09388" target="_blank" rel="noreferrer">paper</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>复杂推理需要更多计算，简单任务需要快速回答；各尺寸分别做完整 RL 成本高。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>预训练</strong>：<code>36T tokens</code>，通识 → 推理数据增强 → 长上下文。</li><li><strong>旗舰后训练</strong>：Long-CoT SFT → Reasoning RL → 模式融合 SFT → General RL。</li><li><strong>小模型蒸馏</strong>：Off-policy 示范 → On-policy Logits 对齐。</li></ul><p><strong>模型效果</strong></p><ul><li>235B-A22B Thinking：AIME’25 <code>81.5</code>、LiveCodeBench v5 <code>70.7</code>、BFCL v3 <code>70.8</code>。</li></ul><p><strong>重要结论</strong></p><ul><li>统一快慢模式可控制推理预算；强教师蒸馏能以较低训练成本提升小模型。</li></ul><p><strong>核心贡献</strong></p><ul><li>将推理控制、通用任务 RL 与强到弱蒸馏整合为全系列训练路线。</li></ul><p><strong>未来方向</strong></p><ul><li>继续提高预训练数据质量和多样性，优化模型压缩与超长上下文。</li><li>扩大基于环境反馈的 Agent RL，并研究更高推理预算下的性能扩展。</li></ul></div><h3 id="问题背景-1" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景-1" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景</div><ul><li>推理、普通对话和 Agent 任务需要不同的响应方式；小模型直接进行大规模 RL 成本较高。</li></ul></div><h3 id="核心方法-1" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法-1" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="架构与预训练" tabindex="-1">架构与预训练 <a class="header-anchor" href="#架构与预训练" aria-label="Permalink to &quot;架构与预训练&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">Dense / MoE 架构</div><p><strong>基础结构</strong></p><ul><li>GQA、SwiGLU、RoPE 和 RMSNorm；移除 QKV Bias，加入 QK-Norm 稳定训练。</li></ul><p><strong>MoE</strong></p><ul><li>旗舰 <code>235B-A22B</code>；每层 <code>128</code> 个专家，每个 Token 选择 <code>8</code> 个，无共享专家。</li><li>使用 Global-batch Load Balancing Loss，在整个 Batch 上平衡负载，保留专家分工。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">PDF 提取、领域合成与细粒度配比</div><p><strong>语料扩展</strong></p><ul><li>Qwen2.5-VL 识别 PDF 文字，再由 Qwen2.5 修订，增加高质量文档数据。</li><li>Qwen2.5 / Math / Coder 合成教材、QA、指令和代码，扩大 STEM 与推理覆盖。</li><li>多语言数据扩展到 <code>119</code> 种语言及方言，总计约 <code>36T tokens</code>。</li></ul><p><strong>样本级配比</strong></p><ul><li>对超过 <code>30T tokens</code> 标注教育价值、领域和安全等属性。</li><li>小型 Proxy Model 做配比消融，根据细粒度标签调整样本，而非只按数据源混合。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">General → Reasoning → Long Context</div><ul><li><strong>S1</strong>：超过 <code>30T tokens</code>，长度 <code>4K</code>，训练语言和通识能力。</li><li><strong>S2</strong>：约 <code>5T tokens</code>，增加 STEM、代码与合成推理数据，加快学习率衰减。</li><li><strong>长上下文</strong>：数千亿 Tokens，长度 <code>32K</code>；长文本 <code>16–32K</code> 占 <code>75%</code>。</li><li>RoPE Base 提高至 <code>1M</code>，推理时配合 YaRN / DCA 扩展至 <code>128K</code>。</li></ul></div><h4 id="四阶段后训练" tabindex="-1">四阶段后训练 <a class="header-anchor" href="#四阶段后训练" aria-label="Permalink to &quot;四阶段后训练&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">Long-CoT 冷启动</div><p><strong>问题筛选</strong></p><ul><li>Qwen2.5-72B-Instruct 去除难以验证的问题，以及无需 CoT 即可答对的简单题。</li><li>按领域平衡数学、代码、逻辑与 STEM，预留独立验证题。</li></ul><p><strong>回答筛选</strong></p><ul><li>QwQ-32B 生成多个候选，保留正确且推理一致的回答。</li><li>过滤重复、猜测、推理与答案矛盾、语言混杂及与验证题相似的样本。</li><li>少量样本、较少训练步数建立推理格式，保留后续 RL 的探索空间。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">Reasoning RL：GRPO 与难题筛选</div><ul><li>选择与冷启动不重合、模型仍可学会且尽量困难的问题，共 <code>3995</code> 个 Query–Verifier 对。</li><li>采用 GRPO、大 Batch、多 Rollout，并利用 Off-policy 训练提高样本效率。</li><li>控制策略熵稳定或缓慢上升，避免过早失去探索多样性。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">Thinking Mode Fusion</div><p><strong>混合 SFT 数据</strong></p><ul><li>Thinking：RL 模型在冷启动题目上做 Rejection Sampling，保持已有推理能力。</li><li>Non-thinking：覆盖写作、代码、问答、多语言等，用自动 Checklist 筛选回答。</li></ul><p><strong>模式控制</strong></p><ul><li><code>/think</code> 与 <code>/no_think</code> 共用模板；直接回答保留空的 <code>&lt;think&gt;</code> 区域。</li><li>多轮对话遵循最后一个模式标记，可在同一会话里切换。</li></ul><p><strong>Thinking Budget</strong></p><ul><li>达到预算后插入结束思考指令，让模型基于已有推理生成最终答案。</li><li>预算适应能力来自模式融合，报告没有单独训练每档预算。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">General RL：多任务奖励</div><p><strong>奖励类型</strong></p><ul><li><strong>规则奖励</strong>：判断答案、格式与可验证约束。</li><li><strong>带参考答案的模型奖励</strong>：Qwen2.5-72B-Instruct 对照参考答案评分。</li><li><strong>无参考答案的偏好奖励</strong>：人类偏好训练的 RM，评价开放任务的帮助性与风格。</li></ul><p><strong>任务覆盖</strong></p><ul><li>覆盖 <code>20+</code> 类任务，包括指令遵循、格式、偏好、RAG 和 Agent。</li><li>Agent Rollout 执行完整多轮工具交互，从真实环境反馈中学习。</li></ul></div><h4 id="强到弱蒸馏" tabindex="-1">强到弱蒸馏 <a class="header-anchor" href="#强到弱蒸馏" aria-label="Permalink to &quot;强到弱蒸馏&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">Strong-to-Weak Distillation</div><p><strong>Off-policy</strong></p><ul><li>用 Qwen3-32B / 235B-A22B 的两种模式示范，训练小模型的基础能力与模式切换。</li></ul><p><strong>On-policy</strong></p><ul><li>学生自行生成回答，教师在学生生成的上下文上给出 Logits。</li><li>最小化学生与教师分布的 KL，使监督覆盖学生实际访问的状态。</li></ul></div><figure style="margin:24px 0;"><img src="https://arxiv.org/html/2505.09388v1/posttrain_pipeline.svg" alt="Qwen3 后训练总流程：大模型依次学习长 CoT、推理 RL、模式融合和通用 RL，再将能力迁移到小模型。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 1：</strong>Qwen3 后训练总流程：大模型依次学习长 CoT、推理 RL、模式融合和通用 RL，再将能力迁移到小模型。 <a href="https://arxiv.org/html/2505.09388#S4.F1" target="_blank" rel="noreferrer">来源</a></figcaption></figure><h3 id="实验设置-qwen3" tabindex="-1">实验设置(Qwen3) <a class="header-anchor" href="#实验设置-qwen3" aria-label="Permalink to &quot;实验设置(Qwen3)&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">实验设置</div><p><strong>模型与训练</strong></p><ul><li>Dense <code>0.6B–32B</code>，MoE <code>30B-A3B / 235B-A22B</code>。</li><li>32B 与 235B-A22B 走四阶段后训练；其余小模型走强到弱蒸馏。</li><li>旗舰 Reasoning RL：<code>3995</code> 个 Query–Verifier 对，示例训练 <code>170</code> 步。</li></ul><p><strong>评测与对照</strong></p><ul><li>AIME 每题采样 <code>64</code> 次，主分数取平均准确率；另报 Pass@64。</li><li>Thinking Budget 对照覆盖数学、代码与 STEM。</li><li>蒸馏消融：同一个 Off-policy 8B Checkpoint，分别继续直接 RL 或 On-policy 蒸馏。</li></ul></div><h3 id="关键结果-qwen3" tabindex="-1">关键结果(Qwen3) <a class="header-anchor" href="#关键结果-qwen3" aria-label="Permalink to &quot;关键结果(Qwen3)&quot;">​</a></h3><div class="custom-block important"><div class="custom-block-title">关键结果</div><p><strong>推理与 Agent</strong></p><ul><li>旗舰 Reasoning RL 的 AIME’24 从 <code>70.1 → 85.1</code>，难题选择与稳定探索持续提高推理能力。</li><li>最终 Thinking 模型：AIME’25 <code>81.5</code>、LCB v5 <code>70.7</code>、BFCL v3 <code>70.8</code>，兼顾推理和工具调用。</li></ul><p><strong>小模型训练效率</strong></p><ul><li>8B 的 AIME’25：继续 RL 为 <code>55.5</code>，On-policy 蒸馏为 <code>65.5</code>；LCB 为 <code>52.9 / 60.3</code>。</li><li>对应训练约 <code>17,920 / 1,800 GPU hours</code>，该对照中蒸馏成本约为直接 RL 的十分之一。</li><li>AIME’25 Pass@64 从 <code>83.3 → 86.7</code>，教师监督也扩展了学生能够解决的问题范围。</li></ul><p><strong>能力与预算</strong></p><ul><li>增大 Thinking Budget 时，数学、代码和 STEM 表现平滑提升。</li><li>General RL 改善指令与通用行为，仍需同时跟踪专项推理能力的变化。</li></ul></div><figure style="margin:24px 0;"><img src="https://arxiv.org/html/2505.09388v1/thinking_budget.svg" alt="Thinking Budget 与任务表现的关系。数学、代码和科学推理对额外推理计算的收益不同，应按任务选择预算。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 2：</strong>Thinking Budget 与任务表现的关系。数学、代码和科学推理对额外推理计算的收益不同，应按任务选择预算。 <a href="https://arxiv.org/html/2505.09388#S4.F2" target="_blank" rel="noreferrer">来源</a></figcaption></figure><h3 id="未来方向-1" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向-1" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block info"><div class="custom-block-title">未来方向</div><p><strong>原文未来方向</strong></p><ul><li>继续提高预训练数据质量和多样性，优化模型压缩与超长上下文。</li><li>扩大基于环境反馈的 Agent RL，并研究更高推理预算下的性能扩展。</li></ul></div><h2 id="_2412-qwen2-5-18t、dpo-→-grpo" tabindex="-1">(2412) Qwen2.5 (18T、DPO → GRPO) <a class="header-anchor" href="#_2412-qwen2-5-18t、dpo-→-grpo" aria-label="Permalink to &quot;(2412) Qwen2.5 (18T、DPO → GRPO)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">Qwen2.5 摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://arxiv.org/abs/2412.15115" target="_blank" rel="noreferrer">paper</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>通用模型需要改善数学代码、长回答、结构化理解和复杂指令遵循。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>预训练</strong>：<code>18T tokens</code>，模型筛选、领域合成与数据配比优化。</li><li><strong>SFT</strong>：超过 <code>1M</code> 样本，重点补充可验证约束、长回答、代码与结构化任务。</li><li><strong>后续对齐</strong>：Offline DPO → Online GRPO，执行核验与 RM 分工。</li></ul><p><strong>模型效果</strong></p><ul><li>72B-Instruct：MATH <code>83.1</code>、HumanEval <code>86.6</code>、Arena-Hard <code>81.2</code>。</li></ul><p><strong>重要结论</strong></p><ul><li>高质量数据与多阶段对齐共同提升能力；RM 榜单得分不一定预测实际 RL 收益。</li></ul><p><strong>核心贡献</strong></p><ul><li>形成从大规模数据构建到分阶段偏好优化的通用模型训练路线。</li></ul><p><strong>未来方向</strong></p><ul><li>持续优化高质量与多样化数据，并把文本、视觉和音频纳入统一多模态框架。</li><li>扩大推理时计算，提高复杂推理能力。</li><li>改进 RM 评估，使其更能预测实际 RL 训练收益。</li></ul></div><h3 id="问题背景-2" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景-2" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景</div><ul><li>需要提升知识、代码、数学和复杂指令的共同表现，并改善长回答与长上下文能力。</li></ul></div><h3 id="核心方法-2" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法-2" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="预训练与长上下文" tabindex="-1">预训练与长上下文 <a class="header-anchor" href="#预训练与长上下文" aria-label="Permalink to &quot;预训练与长上下文&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">18T 预训练数据</div><p><strong>质量筛选与领域配比</strong></p><ul><li>Qwen2-Instruct 从多个维度评估语料质量，覆盖更多语言。</li><li>下采样重复的电商、社交、娱乐内容，上采样科技、科学和学术内容。</li><li>把 Qwen2.5-Math / Coder 的领域数据加入通用预训练。</li></ul><p><strong>合成数据</strong></p><ul><li>Qwen2-72B-Instruct 与 Math 模型生成数学、代码和知识数据。</li><li>通用 RM 与数学 RM 筛选合成内容，再与真实语料混合。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">Scaling Law 与长上下文</div><p><strong>超参数选择</strong></p><ul><li>小规模 Dense / MoE 实验拟合模型量、数据量与最优学习率、Batch Size 的关系。</li><li>按预测结果配置不同尺寸模型，兼顾总参数与激活参数。</li></ul><p><strong>普通分支</strong></p><ul><li>训练长度从 <code>4K → 32K</code>，RoPE Base 提高至 <code>1M</code>。</li><li>推理时用 YaRN / DCA 扩展上下文；7B 及以上开放模型支持 <code>128K</code>。</li></ul><p><strong>Turbo 分支</strong></p><ul><li>训练长度按 <code>32K → 64K → 128K → 256K</code> 扩展，每阶段混合最长序列 <code>40%</code> 与短序列 <code>60%</code>。</li><li>先做短指令 SFT，再混合长短指令；RL 仍用短指令，推理窗口扩展至 <code>1M</code>。</li></ul></div><h4 id="sft-数据构建" tabindex="-1">SFT 数据构建 <a class="header-anchor" href="#sft-数据构建" aria-label="Permalink to &quot;SFT 数据构建&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">长回答、数学与代码</div><p><strong>长回答</strong></p><ul><li>从预训练长文反向构造问题，加入输出长度约束，再筛选问题与答案的一致性。</li></ul><p><strong>数学与代码</strong></p><ul><li>数学用已验证答案、RM 和 Rejection Sampling 筛选 CoT。</li><li>代码使用语言专属 Agent 协作生成指令，覆盖约 <code>40</code> 种编程语言。</li><li>对代码做静态检查，并在多语言 Sandbox 中执行单测。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">指令约束与通用任务</div><p><strong>可验证约束</strong></p><ul><li>模型同时生成指令、验证函数及交叉检查的单测，用执行结果筛选答案。</li><li>例如要求特定字段或长度时，用验证代码判断回答是否满足要求。</li></ul><p><strong>数据覆盖</strong></p><ul><li>表格问答、事实核查和结构理解加入推理过程；逻辑推理新增约 <code>70K</code> 问题。</li><li>高资源语言指令翻译到低资源语言，并检查回答的语义一致性。</li><li>加入数百种 System Prompt；Critic 与多 Agent 打分共同筛选回答。</li></ul></div><h4 id="离线与在线偏好优化" tabindex="-1">离线与在线偏好优化 <a class="header-anchor" href="#离线与在线偏好优化" aria-label="Permalink to &quot;离线与在线偏好优化&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">Offline DPO：执行反馈构造偏好</div><ul><li>SFT 模型在新问题上重新采样，覆盖数学、代码、逻辑和指令约束。</li><li>答案匹配或执行通过作为正例，失败作为负例，再做人工与自动检查。</li><li>固定偏好对执行 DPO，Online Merging Optimizer 缓解对齐后的能力损失。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">Online GRPO：RM 与采样顺序</div><p><strong>Reward Model</strong></p><ul><li>同一问题由不同训练阶段的 SFT / DPO / RL Checkpoint 生成候选，并使用不同温度。</li><li>人工与自动偏好标注共同训练 RM，覆盖真实性、帮助性、简洁性等维度。</li></ul><p><strong>GRPO</strong></p><ul><li>每题采样 <code>8</code> 个回答，用 RM 评分进行组内相对优化。</li><li>优先训练候选得分方差较大的问题，使同组回答提供更有效的区分信号。</li></ul></div><h3 id="实验设置-qwen2-5" tabindex="-1">实验设置(Qwen2.5) <a class="header-anchor" href="#实验设置-qwen2-5" aria-label="Permalink to &quot;实验设置(Qwen2.5)&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">实验设置</div><p><strong>模型与预训练</strong></p><ul><li>开放 Dense <code>0.5B–72B</code>；Turbo / Plus 使用 MoE。</li><li>超参数实验覆盖 Dense <code>44M–14B</code>、MoE 激活参数 <code>44M–1B</code>，训练数据 <code>0.8B–600B</code>。</li></ul><p><strong>SFT 与 DPO</strong></p><ul><li>SFT：<code>1M+</code> 样本、<code>2 epochs</code>、长度 <code>32K</code>；学习率 <code>7e-6 → 7e-7</code>。</li><li>Weight Decay <code>0.1</code>，Gradient Clip <code>1.0</code>。</li><li>DPO：约 <code>150K</code> 偏好对、<code>1 epoch</code>，学习率 <code>7e-7</code>。</li></ul><p><strong>Online RL 与评测</strong></p><ul><li>GRPO：每题 <code>8</code> 个回答，Global Batch Size <code>2048</code>，每 Episode <code>2048</code> 个问答样本。</li><li>分别评估 Base、Instruct、长上下文与 RM；RM 另测 RewardBench、RMB、PPE 和中文偏好。</li></ul></div><h3 id="关键结果-qwen2-5" tabindex="-1">关键结果(Qwen2.5) <a class="header-anchor" href="#关键结果-qwen2-5" aria-label="Permalink to &quot;关键结果(Qwen2.5)&quot;">​</a></h3><div class="custom-block important"><div class="custom-block-title">关键结果</div><p><strong>推理与对齐</strong></p><ul><li>72B-Instruct 的 MATH 达 <code>83.1</code>，高于 Qwen2-72B 的 <code>69.0</code>；HumanEval 达 <code>86.6</code>。</li><li>Arena-Hard 达 <code>81.2</code>，多阶段后训练明显改善开放任务的回答质量。</li></ul><p><strong>长上下文</strong></p><ul><li>Turbo 分支扩展到 <code>1M</code> 窗口；长文本训练与长指令 SFT 共同支持长文检索和理解。</li></ul><p><strong>RM 选择</strong></p><ul><li>不同 RM 在 RewardBench、RMB 和 PPE 上的排名不同，单一榜单无法全面衡量反馈质量。</li><li>报告发现 RM 测试分数更高时，训练出的策略未必更好；需结合下游 RL 结果选择 RM。</li></ul></div><figure style="margin:24px 0;"><img src="https://arxiv.org/html/2412.15115v2/passkey_retrieval.png" alt="Qwen2.5-Turbo 的 1M Passkey Retrieval：横轴是上下文长度，纵轴是目标位置，观察长窗口内不同深度的检索覆盖。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 2：</strong>Qwen2.5-Turbo 的 1M Passkey Retrieval：横轴是上下文长度，纵轴是目标位置，观察长窗口内不同深度的检索覆盖。 <a href="https://arxiv.org/html/2412.15115#S5.F2" target="_blank" rel="noreferrer">来源</a></figcaption></figure><h3 id="未来方向-2" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向-2" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block info"><div class="custom-block-title">未来方向</div><p><strong>原文未来方向</strong></p><ul><li>持续优化高质量与多样化数据，并把文本、视觉和音频纳入统一多模态框架。</li><li>扩大推理时计算，提高复杂推理能力。</li><li>改进 RM 评估，使其更能预测实际 RL 训练收益。</li></ul></div><h2 id="_2409-qwen2-5-coder-文件与仓库-cpt、sft-dpo" tabindex="-1">(2409) Qwen2.5-Coder (文件与仓库 CPT、SFT+DPO) <a class="header-anchor" href="#_2409-qwen2-5-coder-文件与仓库-cpt、sft-dpo" aria-label="Permalink to &quot;(2409) Qwen2.5-Coder (文件与仓库 CPT、SFT+DPO)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">Qwen2.5-Coder 摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://arxiv.org/abs/2409.12186" target="_blank" rel="noreferrer">paper</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>Code 模型需缩小与闭源模型的差距，同时保持数学、自然语言与多语言代码能力。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>CPT</strong>：文件级 <code>5.2T</code> + 仓库级 <code>300B</code>，联合 NTP / FIM。</li><li><strong>数据构建</strong>：网页分层筛选、多语言 Agent 合成、Checklist 与执行验证。</li><li><strong>后训练</strong>：Coarse-to-fine SFT，混入 FIM，再做 Offline DPO。</li></ul><p><strong>模型效果</strong></p><ul><li>32B-Instruct：HumanEval <code>92.7</code>、BigCodeBench Instruct <code>49.6</code>、Aider Pass@1 <code>60.9</code>。</li></ul><p><strong>重要结论</strong></p><ul><li>高质量文字—代码关联数据有效；混合通用文本与数学数据可保持更全面的能力。</li></ul><p><strong>核心贡献</strong></p><ul><li>提供从代码语料、仓库上下文到执行反馈偏好的完整 Code 模型训练路线。</li></ul><p><strong>未来方向</strong></p><ul><li>继续扩展代码数据与模型规模，并提高代码推理能力。</li><li>研究更有效的 Code / Text / Math 配比，解释跨领域数据带来的迁移收益。</li></ul></div><h3 id="问题背景-3" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景-3" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景</div><ul><li>Code 模型需要同时理解文件和仓库结构，指令数据还要覆盖大量低资源编程语言。</li></ul></div><h3 id="核心方法-3" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法-3" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="code-数据与继续预训练" tabindex="-1">Code 数据与继续预训练 <a class="header-anchor" href="#code-数据与继续预训练" aria-label="Permalink to &quot;Code 数据与继续预训练&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">源码、解释性网页与合成数据</div><p><strong>源码</strong></p><ul><li>收集 <code>2024-02</code> 前 GitHub 仓库，覆盖 <code>92</code> 种编程语言，按规则清洗。</li><li>同时收集 PR、Commit、Notebook 和 Kaggle，扩充代码上下文。</li></ul><p><strong>Text-Code Grounding</strong></p><ul><li>从 Common Crawl 提取文档、教程和博客，保留文字与代码的对应关系。</li><li>用 fastText 等小模型做 <code>4</code> 层由粗到细的筛选，每层分别控制相关性与质量。</li><li>保留各层质量分，供后续数据混合使用。</li></ul><p><strong>合成与混合</strong></p><ul><li>CodeQwen1.5 合成代码，经 Executor 验证后保留可执行样本。</li><li>加入 Qwen2.5 的通用文本和 Math 数据；通用文本先移除代码，减少来源重叠。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">文件级与仓库级 CPT</div><p><strong>File-level</strong></p><ul><li>从 Qwen2.5 开始继续预训练，<code>5.2T tokens</code>、长度 <code>8K</code>。</li><li>联合 Next-token Prediction 与 FIM，输入缺口前后文，预测中间代码。</li></ul><p><strong>Repo-level</strong></p><ul><li>继续训练约 <code>300B tokens</code>，长度扩至 <code>32K</code>，RoPE Base 提至 <code>1M</code>。</li><li>用 Repo Name、File Separator 与文件路径组织上下文，把 FIM 扩展到多文件代码。</li><li>推理时通过 YaRN 外推至 <code>128K</code>。</li></ul></div><h4 id="多语言指令数据" tabindex="-1">多语言指令数据 <a class="header-anchor" href="#多语言指令数据" aria-label="Permalink to &quot;多语言指令数据&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">指令合成与语言协作</div><p><strong>指令来源</strong></p><ul><li>从 GitHub 代码片段反向生成问题，再由 Code LLM 生成回答、评分筛选。</li><li>混合开源多语言指令；CodeBERT 识别编程语言，控制各语言及无代码样本比例。</li></ul><p><strong>多 Agent 协作</strong></p><ul><li>每种语言由专属 Agent 生成指令和解法，再通过跨语言讨论共享问题模式。</li><li>Memory 记录生成历史，减少重复；根据各语言的知识缺口补充新问题。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">Checklist 与多语言 Sandbox</div><p><strong>质量打分</strong></p><ul><li>检查问答一致性、难度、代码正确性、规范、可读性和教学价值，按权重汇总。</li></ul><p><strong>代码验证</strong></p><ul><li>解析 AST，过滤语法错误。</li><li>对可独立运行的算法题自动生成单测，检查正常输入和边界情况。</li><li>Sandbox 负责隔离执行、超时控制和结果比较，保留通过验证的数据。</li></ul></div><h4 id="sft-与偏好优化" tabindex="-1">SFT 与偏好优化 <a class="header-anchor" href="#sft-与偏好优化" aria-label="Permalink to &quot;SFT 与偏好优化&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">两阶段 SFT 与 FIM 混合</div><p><strong>Coarse-to-fine</strong></p><ul><li>第一阶段使用数千万条多样化合成指令，扩大任务覆盖。</li><li>第二阶段使用数百万高质量样本；同题生成多个候选，评分后选优做 SFT。</li></ul><p><strong>Mixed Tuning</strong></p><ul><li>主要使用普通 SFT 样本，混入少量 FIM 指令，保持补全与长上下文能力。</li><li>Tree-sitter 解析 AST，抽取表达式、语句或函数等逻辑块作为待补全内容。</li></ul></div><figure style="margin:24px 0;"><img src="https://arxiv.org/html/2409.12186v3/qwen2.5-coder-pipeline.svg" alt="Qwen2.5-Coder 的三阶段训练：文件级训练积累代码能力，仓库级训练建立跨文件联系，再以指令训练对齐开发任务。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 2：</strong>Qwen2.5-Coder 的三阶段训练：文件级训练积累代码能力，仓库级训练建立跨文件联系，再以指令训练对齐开发任务。 <a href="https://arxiv.org/html/2409.12186#S3.F2" target="_blank" rel="noreferrer">来源</a></figcaption></figure><div class="custom-block tip"><div class="custom-block-title">执行反馈与模型偏好</div><ul><li>算法题、独立代码：用多语言 Sandbox 的测试通过情况构造偏好。</li><li>复杂代码：LLM-as-a-Judge 比较候选质量。</li><li>代码偏好与通用偏好数据混合，执行 Offline DPO。</li></ul></div><h3 id="实验设置-qwen2-5-coder" tabindex="-1">实验设置(Qwen2.5-Coder) <a class="header-anchor" href="#实验设置-qwen2-5-coder" aria-label="Permalink to &quot;实验设置(Qwen2.5-Coder)&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">实验设置</div><p><strong>模型与预训练</strong></p><ul><li>Qwen2.5 基座，<code>0.5B / 1.5B / 3B / 7B / 14B / 32B</code> 六档。</li><li>总 CPT 约 <code>5.5T tokens</code>；文件阶段 Code / Text / Math 为 <code>70 / 20 / 10</code>。</li></ul><p><strong>数据消融</strong></p><ul><li>1.5B 比较解释性网页逐层过滤；7B 比较纯 Code 与不同混合配比。</li><li>Base 评估生成、FIM、仓库补全、推理和长上下文；Instruct 另评编辑、SQL 与表格任务。</li></ul><p><strong>后训练</strong></p><ul><li>大规模多样 SFT → 高质量 Rejection Sampling SFT → Offline DPO。</li><li>代码执行验证适用于可独立运行的片段；其余代码使用模型评审。</li></ul></div><h3 id="关键结果-qwen2-5-coder" tabindex="-1">关键结果(Qwen2.5-Coder) <a class="header-anchor" href="#关键结果-qwen2-5-coder" aria-label="Permalink to &quot;关键结果(Qwen2.5-Coder)&quot;">​</a></h3><div class="custom-block important"><div class="custom-block-title">关键结果</div><p><strong>生成与编辑</strong></p><ul><li>32B-Instruct 的 HumanEval <code>92.7</code>、BigCodeBench Instruct <code>49.6</code>，提升覆盖标准题和更复杂依赖代码。</li><li>Aider Pass@1 <code>60.9</code>，说明收益也覆盖根据要求修改现有代码。</li></ul><p><strong>数据质量</strong></p><ul><li>1.5B 的 HumanEval / MBPP 平均分在网页分层筛选后从 <code>41.6 → 46.8</code>。</li><li>文字解释与代码关联数据提供了纯源码之外的监督，筛选比直接扩大网页量更有效。</li></ul><p><strong>混合配比</strong></p><ul><li>加入 Text / Math 明显改善通用与数学任务，同时保持代码能力。</li><li>代码比例不是越高越好，配比应结合代码表现与通用能力共同选择。</li></ul></div><h3 id="未来方向-3" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向-3" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block info"><div class="custom-block-title">未来方向</div><p><strong>原文未来方向</strong></p><ul><li>继续扩展代码数据与模型规模，并提高代码推理能力。</li><li>研究更有效的 Code / Text / Math 配比，解释跨领域数据带来的迁移收益。</li></ul></div><h2 id="_2407-qwen2-7t、离线与在线-dpo" tabindex="-1">(2407) Qwen2 (7T、离线与在线 DPO) <a class="header-anchor" href="#_2407-qwen2-7t、离线与在线-dpo" aria-label="Permalink to &quot;(2407) Qwen2 (7T、离线与在线 DPO)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">Qwen2 摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://arxiv.org/abs/2407.10671" target="_blank" rel="noreferrer">paper</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>通用模型需要同时增强代码、数学、多语言和长上下文，并降低高质量对齐数据的标注成本。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>架构</strong>：GQA Dense，细粒度 MoE 由 7B Upcycling。</li><li><strong>数据</strong>：高质量 <code>7T</code> 语料；指令标签、难度演化与按任务自动验证。</li><li><strong>后训练</strong>：SFT → Offline DPO → 当前策略采样的 Online DPO。</li></ul><p><strong>模型效果</strong></p><ul><li>72B-Instruct：HumanEval <code>86.0</code>、MATH <code>69.0</code>、Arena-Hard <code>48.1</code>。</li></ul><p><strong>重要结论</strong></p><ul><li>扩大数据要保持质量；自动执行与答案核验可同时产生示范和偏好数据。</li></ul><p><strong>核心贡献</strong></p><ul><li>建立可扩展的数据对齐流程，并将 Dense / MoE 与长上下文纳入同一模型系列。</li></ul><p><strong>未来方向</strong></p><ul><li>提高小模型后训练数据的质量，尤其是复杂指令和约束遵循。</li><li>继续优化数据过滤与领域配比，提高扩充数据时的有效信息密度。</li></ul></div><h3 id="问题背景-4" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景-4" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景</div><ul><li>扩大多语言与代码能力后，仍需提升指令遵循和用户偏好对齐，并兼顾模型推理效率。</li></ul></div><h3 id="核心方法-4" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法-4" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="架构与预训练-1" tabindex="-1">架构与预训练 <a class="header-anchor" href="#架构与预训练-1" aria-label="Permalink to &quot;架构与预训练&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">GQA 与细粒度 MoE</div><p><strong>Dense</strong></p><ul><li>GQA 减少 KV Cache；SwiGLU、RoPE、RMSNorm 与 Pre-norm 保持训练稳定。</li></ul><p><strong>MoE</strong></p><ul><li>57B-A14B 从 Qwen2-7B Upcycling，使用细粒度路由专家和共享专家。</li><li>每层 <code>64</code> 个路由专家，选择 <code>8</code> 个，另有 <code>8</code> 个共享专家。</li><li>复制 Dense FFN，沿中间维度打乱并切分为小专家，再随机重初始化一半参数。</li><li>不同专家保留基座知识，同时增加初始化差异，减少所有专家学习相同功能。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">预训练数据与长上下文</div><p><strong>数据质量</strong></p><ul><li>规则与 Qwen 模型联合过滤，扩充代码、数学和约 <code>30</code> 种语言的数据。</li><li>小模型实验优化来源与领域配比，加入高质量指令数据增强 ICL。</li></ul><p><strong>长上下文</strong></p><ul><li>预训练末期从 <code>4K → 32K</code>，增加长文，RoPE Base 从 <code>10K → 1M</code>。</li><li>DCA 处理块内与块间相对位置，配合 YaRN 做长度外推。</li></ul></div><h4 id="指令数据与偏好训练" tabindex="-1">指令数据与偏好训练 <a class="header-anchor" href="#指令数据与偏好训练" aria-label="Permalink to &quot;指令数据与偏好训练&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">指令标签与难度演化</div><p><strong>指令选择</strong></p><ul><li>InsTag 提取细粒度标签，人工修订后按多样性、复杂度和意图完整性选题。</li><li>Qwen 给已有指令增加约束，扩展难度层次。</li></ul><p><strong>人工偏好</strong></p><ul><li>不同尺寸模型与采样策略生成多个回答，人工排序。</li><li>最佳回答用于 SFT，正负回答对用于后续 DPO。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">按任务构造自动监督</div><p><strong>数学与代码</strong></p><ul><li>数学：多条推理路径采样，保留答案正确且过程合理的路径，正误配对形成偏好。</li><li>代码：生成解法与测试，编译执行后同时得到示范与偏好数据。</li></ul><p><strong>指令、写作与角色</strong></p><ul><li>约束指令：生成 Python 验证函数，检查长度、格式等条件。</li><li>写作：从高质量作品反向生成不同细度的指令。</li><li>角色：基于人物资料生成问答，保持角色信息一致。</li></ul><p><strong>Constitutional Feedback</strong></p><ul><li>根据预设原则生成遵循与违反原则的回答，为安全任务提供正负反馈。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">SFT → Offline DPO → Online DPO</div><p><strong>SFT</strong></p><ul><li>混合指令、代码、数学、逻辑、角色、多语言和安全任务，学习完整回答。</li></ul><p><strong>Offline DPO</strong></p><ul><li>固定人工与合成偏好对，提高正例相对负例的生成概率。</li></ul><p><strong>Online DPO</strong></p><ul><li>当前策略对问题生成多个回答，由 RM 选择最好和最差的候选。</li><li>每个 Episode 重新构造偏好对，继续做 DPO；使用 Online Merging Optimizer 缓解对齐损失。</li></ul></div><h3 id="实验设置-qwen2" tabindex="-1">实验设置(Qwen2) <a class="header-anchor" href="#实验设置-qwen2" aria-label="Permalink to &quot;实验设置(Qwen2)&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">实验设置</div><p><strong>模型与数据</strong></p><ul><li>Dense <code>0.5B / 1.5B / 7B / 72B</code>，MoE <code>57B-A14B</code>。</li><li>多数 Dense 训练 <code>7T tokens</code>，0.5B 使用 <code>12T</code>；MoE Upcycling 后追加 <code>4.5T</code>。</li></ul><p><strong>SFT</strong></p><ul><li>超过 <code>500K</code> 样本、<code>2 epochs</code>、长度 <code>32K</code>。</li><li>学习率 <code>7e-6 → 7e-7</code>，Weight Decay <code>0.1</code>，Gradient Clip <code>1.0</code>。</li></ul><p><strong>评测与对照</strong></p><ul><li>分别测 Base 和 Instruct，覆盖代码、数学、通用、多语言、指令与长上下文。</li><li>以 Qwen1.5、同量级 Dense / MoE 为对照；数据实验比较高质量 <code>7T</code> 与放宽筛选后的 <code>12T</code>。</li></ul></div><h3 id="关键结果-qwen2" tabindex="-1">关键结果(Qwen2) <a class="header-anchor" href="#关键结果-qwen2" aria-label="Permalink to &quot;关键结果(Qwen2)&quot;">​</a></h3><div class="custom-block important"><div class="custom-block-title">关键结果</div><p><strong>代码与数学</strong></p><ul><li>72B-Instruct 相对 Qwen1.5-72B：HumanEval <code>71.3 → 86.0</code>，MATH <code>42.5 → 69.0</code>。</li><li>多语言代码 MultiPL-E 从 <code>48.1 → 69.2</code>，收益覆盖 Python 之外的语言。</li></ul><p><strong>对齐与数据</strong></p><ul><li>Arena-Hard 从 <code>36.1 → 48.1</code>，说明后训练也改善开放任务的偏好表现。</li><li>放宽质量门槛得到 <code>12T</code> 后未出现明显收益，大模型选择使用更高质量的 <code>7T</code>。</li></ul><p><strong>小模型短板</strong></p><ul><li>7B 代码能力有竞争力，但复杂指令遵循仍落后于 Llama-3-8B。</li><li>领域分数提升不能代替指令评估，需专门补充高质量约束任务。</li></ul></div><h3 id="未来方向-4" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向-4" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block info"><div class="custom-block-title">未来方向</div><p><strong>原文讨论的方向</strong></p><ul><li>提高小模型后训练数据的质量，尤其是复杂指令和约束遵循。</li><li>继续优化数据过滤与领域配比，提高扩充数据时的有效信息密度。</li></ul></div>',140)]))}const h=o(n,[["render",s]]);export{p as __pageData,h as default};
